import { tool, createSdkMcpServer } from "@anthropic-ai/claude-agent-sdk";
import { z } from "zod";

const checkOrderStatus = tool(
  "check_order_status",
  "Read-only lookup of an order's status (pending, shipped, delivered, " +
    "refunded, cancelled) and its payment history. Has no side effects — " +
    "ALWAYS use before process_refund or issue_partial_credit to confirm " +
    "the order exists and is in an eligible state.",
  { order_id: z.string().describe("Order ID, format ORD-XXXXXX") },
  async ({ order_id }) => {
    const order = await lookupOrder(order_id);
    if (!order) {
      return { content: [{ type: "text", text: `No order exists with ID ${order_id}.` }], isError: true };
    }
    return { content: [{ type: "text", text: JSON.stringify(order) }] };
  }
);

const processRefund = tool(
  "process_refund",
  "Issues a FULL refund of the original order amount, returned to the " +
    "original payment method. Use ONLY when the customer asks to fully " +
    "cancel the purchase (product not received, full cancellation, " +
    "duplicate charge). Do NOT use for partial discounts or compensation " +
    "for minor inconveniences — that's what issue_partial_credit is for. " +
    "Precondition: the order must be in 'shipped' or 'delivered' state " +
    "(verify with check_order_status first). Refunds above the configured " +
    "threshold are blocked before execution — see the PreToolUse hook in " +
    "Step 4.",
  {
    order_id: z.string().describe("Order ID, format ORD-XXXXXX"),
    amount: z.number().describe("Amount to refund in USD — must match the order's actual amount"),
    reason: z.enum(["not_received", "duplicate_charge", "full_cancellation", "other"]),
  },
  async ({ order_id, amount, reason }) => {
    // The PreToolUse hook already blocked this call if amount > 500 — only
    // the allowed case reaches here.
    await issueRefund(order_id, amount);
    return { content: [{ type: "text", text: `Refund of $${amount} processed for order ${order_id}.` }] };
  }
);

const issuePartialCredit = tool(
  "issue_partial_credit",
  "Issues a partial STORE CREDIT (not a refund to the original payment " +
    "method) as compensation for a minor inconvenience (shipping delay, " +
    "damaged-but-usable packaging, minor billing error). Maximum amount " +
    "per call is 50 USD equivalent. Do NOT use if the customer explicitly " +
    "asks for their money back — in that case use process_refund or " +
    "escalate_to_human, not this tool.",
  {
    customer_id: z.string(),
    amount_usd: z.number().max(50).describe("Amount in USD, maximum 50"),
    reason: z.enum(["shipping_delay", "minor_damage", "billing_error"]),
  },
  async ({ customer_id, amount_usd, reason }) => {
    await creditAccount(customer_id, amount_usd);
    return { content: [{ type: "text", text: `$${amount_usd} credit issued for customer ${customer_id}.` }] };
  }
);

const escalateToHuman = tool(
  "escalate_to_human",
  "Transfers the conversation to a human agent, preserving the full " +
    "context. Use when: (a) the request falls outside the policy defined " +
    "for the other tools, (b) the customer explicitly asks to talk to a " +
    "person, or (c) a call to process_refund was blocked for exceeding the " +
    "authorized threshold. This is the only valid exit for ambiguous cases.",
  {
    summary: z.string().describe("Case summary for the human agent"),
    urgency: z.enum(["low", "normal", "high"]).default("normal"),
  },
  async ({ summary, urgency }) => {
    const ticketId = await createEscalationTicket(summary, urgency);
    return { content: [{ type: "text", text: `Case escalated. Ticket ${ticketId} created with urgency ${urgency}.` }] };
  }
);

export const supportServer = createSdkMcpServer({
  name: "support",
  version: "1.0.0",
  tools: [checkOrderStatus, processRefund, issuePartialCredit, escalateToHuman],
});
// Each tool is exposed to the model as mcp__support__<name>,
// e.g. mcp__support__process_refund.

// This is what query() does internally on every turn — it's not code
// the Agent SDK user writes, it's the mechanics that explain why the
// SDK can abstract the loop without changing behavior:
//
//   1. Send the conversation to Claude.
//   2. If stop_reason === 'tool_use': execute the requested tools,
//      reinject the tool_result, go back to 1.
//   3. If stop_reason === 'end_turn': finish and deliver the result.
//
// As an SDK consumer, you don't see steps 1-2 turn by turn — you consume
// the message stream and the terminal stop_reason arrives in the result.

import { query } from "@anthropic-ai/claude-agent-sdk";
import { supportServer } from "../mcp/support-server";
import { blockLargeRefunds } from "./hooks"; // see Step 4

export async function runSupportAgent(userMessage: string) {
  for await (const message of query({
    prompt: userMessage,
    options: {
      mcpServers: { support: supportServer },
      allowedTools: ["mcp__support__*"],
      hooks: {
        PreToolUse: [{ matcher: "mcp__support__process_refund", hooks: [blockLargeRefunds] }],
      },
    },
  })) {
    // message.type is 'assistant' | 'user' | 'result' | ... — stop_reason
    // does NOT appear here, only in the final 'result' message.
    if (message.type === "result") {
      if (message.subtype === "success") {
        console.log(message.result);
      } else {
        // 'error_max_turns' | 'error_max_budget_usd' | 'error_during_execution' | ...
        console.error(`Session ended without success: ${message.subtype}`);
      }
      console.log("stop_reason:", message.stop_reason); // 'end_turn' expected
      return message;
    }
  }
}

export type ErrorCategory = "transient" | "validation" | "business" | "permission";

export interface StructuredToolError {
  errorCategory: ErrorCategory;
  isRetryable: boolean;
  message: string;
}

export function buildErrorContent(category: ErrorCategory, message: string) {
  const error: StructuredToolError = {
    errorCategory: category,
    isRetryable: category === "transient",
    message,
  };
  // The text carries the structured JSON — the isError flag lives one
  // level up, on the object the tool returns (see Step 1 and Step 4).
  return { content: [{ type: "text" as const, text: JSON.stringify(error) }], isError: true };
}

