import type { HookCallback, PreToolUseHookInput } from "@anthropic-ai/claude-agent-sdk";

const REFUND_ESCALATION_THRESHOLD_USD = 500;

export const blockLargeRefunds: HookCallback = async (input, _toolUseID, _opts) => {
  const preInput = input as PreToolUseHookInput;

  if (preInput.tool_name !== "mcp__support__process_refund") {
    return {}; // not the tool we care about: don't intervene
  }

  const toolInput = preInput.tool_input as { order_id: string; amount: number };

  // Source of truth: the order's actual amount in the database, NOT the
  // `amount` field the model included in the input — the hook must never
  // validate a business rule against data the model itself controls,
  // because that reintroduces the probabilistic failure surface the hook
  // exists to eliminate.
  const order = await lookupOrderAmount(toolInput.order_id);

  if (order.amount_usd > REFUND_ESCALATION_THRESHOLD_USD) {
    return {
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        permissionDecision: "deny",
        permissionDecisionReason:
          `Refund of $${order.amount_usd} exceeds the authorized threshold of ` +
          `$${REFUND_ESCALATION_THRESHOLD_USD}. Do not retry process_refund for this ` +
          `order — use escalate_to_human with the case details.`,
      },
    };
  }

  return {}; // within threshold: let the tool run
};

