import { query, type AgentDefinition } from "@anthropic-ai/claude-agent-sdk";

const webResearchAgent: AgentDefinition = {
  description: "Searches the web for current information on a specific topic and returns findings with source and date",
  tools: ["WebSearch", "WebFetch"],
  prompt: WEB_RESEARCH_SYSTEM_PROMPT, // see Step 3: requires the structured finding format
  model: "sonnet",
};

const documentAnalysisAgent: AgentDefinition = {
  description: "Analyzes already-provided internal documents (PDFs, reports) and extracts findings relevant to a question",
  tools: ["Read", "Grep"],
  prompt: DOCUMENT_ANALYSIS_SYSTEM_PROMPT,
  model: "sonnet",
};

export async function runCoordinator(researchQuestion: string) {
  for await (const message of query({
    prompt: buildCoordinatorPrompt(researchQuestion),
    options: {
      allowedTools: ["Task"], // the coordinator ONLY delegates, it doesn't research itself
      agents: {
        "web-research": webResearchAgent,
        "document-analysis": documentAnalysisAgent,
      },
    },
  })) {
    handleCoordinatorMessage(message);
  }
}

function buildCoordinatorPrompt(question: string): string {
  return `Research question: "${question}"

Delegate this question to the relevant subagents. For each Task
invocation, include in the subagent's prompt the specific context it
needs (the specific sub-question, not the full unscoped question) — the
subagents do NOT inherit this conversation, they only receive what you
explicitly pass them in the Task prompt.`;
}

// Coordinator prompt that induces parallelism when appropriate:
const COORDINATOR_SYSTEM_PROMPT = `When a research question decomposes
into independent sub-questions (none needs another's result to start),
emit ALL of them as Task calls in the same response — don't wait for one
result before launching the next. If a sub-question does depend on
another's result, execute them in the necessary order.`;

// Measuring the latency improvement (benchmark harness, not production
// code):
async function benchmarkParallelVsSequential(question: string) {
  const t0 = performance.now();
  await runCoordinator(question); // coordinator with the prompt above -> parallel
  const parallelMs = performance.now() - t0;

  const t1 = performance.now();
  await runSequentialBaseline(question); // variant forced to one Task at a time
  const sequentialMs = performance.now() - t1;

  return { parallelMs, sequentialMs, speedup: sequentialMs / parallelMs };
}

// Typical result with 2 subagents of ~20s each:
// sequential: ~40s (20s + 20s in series)
// parallel:   ~22s (both run at once, dominated by the slower one + overhead)
// speedup: ~1.8x

interface Finding {
  claim: string;             // the claim itself
  evidence_excerpt: string;  // a direct quote that supports it, not a summary
  source: string;            // exact URL or document identifier
  published_date: string | null; // ISO 8601, or null if the source doesn't state it
}

const WEB_RESEARCH_SYSTEM_PROMPT = `Research the assigned sub-question using
WebSearch and WebFetch. Return each finding as an object with exactly
these fields: claim, evidence_excerpt (a direct quote, not a paraphrase),
source (full URL), published_date (ISO 8601 or null if the page doesn't
state it). Don't mix these fields into free prose — they need to be
separate so the synthesis subagent can attribute each claim to its source.`;

// The synthesis subagent receives a Finding[] array from each subagent,
// never unstructured free-text summaries:
const SYNTHESIS_SYSTEM_PROMPT = `You received structured findings from
multiple subagents. When synthesizing the final report, every claim must
continue citing its original source in brackets, e.g.: "Adoption rate grew
40% in 2025 [source: gartner.com/report-2025]." Never combine two findings
from different sources into a single sentence without attributing each
part to its corresponding source.`;

interface SubagentFailure {
  agentId: string;
  failureType: "timeout" | "tool_error" | "empty_result";
  attemptedQuery: string;
  partialResults: Finding[]; // whatever was collected before failing
}

async function runSubagentWithTimeout(
  agentKey: string,
  subQuestion: string,
  timeoutMs = 45_000
): Promise<Finding[] | SubagentFailure> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const results = await invokeSubagent(agentKey, subQuestion, controller.signal);
    clearTimeout(timer);
    return results;
  } catch (e) {
    clearTimeout(timer);
    return {
      agentId: agentKey,
      failureType: controller.signal.aborted ? "timeout" : "tool_error",
      attemptedQuery: subQuestion,
      partialResults: extractPartialResults(e), // whatever was collected until the failure
    };
  }
}

function isFailure(r: Finding[] | SubagentFailure): r is SubagentFailure {
  return "failureType" in r;
}

async function synthesizeWithGaps(results: (Finding[] | SubagentFailure)[]) {
  const successful = results.filter((r): r is Finding[] => !isFailure(r)).flat();
  const failures = results.filter(isFailure);

  const report = await synthesize(successful);

  if (failures.length > 0) {
    report.coverageGaps = failures.map(f =>
      `Could not complete research on "${f.attemptedQuery}" ` +
      `(${f.failureType}). ${f.partialResults.length > 0
        ? `Included ${f.partialResults.length} partial findings collected before the failure.`
        : "No findings were collected before the failure."}`
    );
  }

  return report;
}

const SYNTHESIS_SYSTEM_PROMPT_CONFLICTS = `When synthesizing findings from
multiple sources:

1. If two or more independent sources agree on a fact, present it in the
   "Well-established findings" section.
2. If credible sources report DIFFERENT values for the same fact
   (e.g. a statistic), do NOT arbitrarily pick one nor average the
   values. Present it in the "Disputed points" section, listing each
   value with its exact source:
   "The reported adoption rate varies by source: 40% according to
   Gartner [gartner.com/...] vs. 28% according to Forrester
   [forrester.com/...]. Possible causes for the discrepancy: different
   measurement methodology or covered period."
3. Never present a disputed value as if it were a consolidated fact just
   because it appeared first in the received findings.`;

// Example expected output structure from the synthesis subagent:
interface SynthesisReport {
  establishedFindings: Finding[];         // consensus across sources
  disputedFindings: {
    topic: string;
    values: { claim: string; source: string }[]; // all conflicting values, none chosen
    note: string; // possible cause of the discrepancy, if inferable
  }[];
  coverageGaps?: string[]; // from Step 4
}
